  "shortcuts.interactiveHelp": "Włącz lub wyłącz pomoc interaktywną",
  "installHint.chromium": "Zainstaluj ikoną po prawej stronie paska adresu albo z menu przeglądarki, opcją „Zainstaluj jako aplikację”.",
  "installHint.safariMac": "W Safari: menu Plik → „Dodaj do Docka”.",
  "installHint.ios": "W Safari: ikona Udostępnij → „Do ekranu początkowego”.",
  "installHint.firefox": "Firefox nie instaluje aplikacji, ale layerling i tak uruchomi się tu offline w karcie.",
  "welcome.moreLanguagesTitle": "Twój język",
  "welcome.moreLanguagesBody": "program i jego instrukcja mówią po angielsku, niemiecku i w 17 innych językach. Lista języków jest w prawym górnym rogu oraz w ustawieniach na stronie startowej.",
  "welcome.moreOfflineTitle": "Działa offline",
  "welcome.moreOfflineBody": "po pierwszej wizycie layerling uruchamia się także bez internetu. Zainstaluj go jak zwykły program, a projekty zostaną na Twoim komputerze.",
  "welcome.moreAiTitle": "Budowanie z AI",
  "welcome.moreAiBody": "przez interfejs MCP asystent AI może tworzyć i edytować kształty w edytorze, który sam otwiera. Wymaga to kopii uruchomionej u siebie (npm run dev albo obraz Docker). Na layerling.com połączenie z AI jest wyłączone.",
  "welcome.morePointsTitle": "Punkty odniesienia",
  "welcome.moreSearchTitle": "Wyszukiwanie poleceń",
  "welcome.moreSimplifyTitle": "Upraszczanie siatek",
  "welcome.moreSimplifyBody": "Zaimportowana siatka z bardzo dużą liczbą trójkątów zostaje zmniejszona do ułamka, z widokiem przed i po oraz suwakiem, więc cięcie, grupowanie i przeciąganie pozostają płynne.",
  "welcome.moreHistoryTitle": "Historia",
  "welcome.moreLookTitle": "Wygląd według Ciebie",
  "welcome.moreLookBody": "Tło i płaszczyznę roboczą, strzałki osi X, Y i Z, linie krawędzi na każdej bryle, kolory szkicu, a także kontrast, cienie i kierunek światła ustawisz w ustawieniach, np. żeby ciemne bryły się nie zlewały. Na wolniejszych komputerach tryb szybki wyłącza naraz wszystko, co kosztowne.",
  "welcome.moreControlsTitle": "Mysz i mysz 3D",
  "welcome.moreControlsBody": "pozwala, jeśli chcesz, ustawić przyciski myszy jak w Bambu Studio i OrcaSlicer (przeciągnięcie lewym po pustym miejscu obraca widok, prawy przycisk go przesuwa) i sterować widokiem myszą SpaceMouse w Chrome i Edge.",
  "welcome.moreHistoryBody": "suwakiem wróć do dowolnego wcześniejszego stanu projektu, niczego nie zmieniając. Ten stan możesz wyeksportować, zacząć od niego nowy projekt albo przywrócić z niego pojedyncze obiekty. Cofnij i Ponów podają krok, który wycofują, razem z jego wartością, a lista wymienia wszystkie kroki, do których można przeskoczyć.",
  "welcome.moreDrawingTitle": "Rysunek dla warsztatu",
  "welcome.moreDrawingBody": "Eksport → Rysunek: widok z przodu, z góry i z boku w skali 1:1 na arkuszu ISO, z wymiarami gabarytowymi, krawędziami niewidocznymi i tabelą okrągłych otworów, jako PDF lub SVG, do wydruku albo do zaniesienia do tokarki i frezarki. Widok z góry jako SVG albo DXF trafia do lasera, jeśli chcesz z mostkami szablonowymi, które trzymają środek litery o albo b.",
  "welcome.moreSearchBody": "Naciśnij Ctrl+K i wpisz nazwę narzędzia, kształtu lub polecenia, aby od razu do niego przejść. Obok każdego widać skrót klawiszowy. Bryły Twojego projektu też można znaleźć po nazwie.",
  "welcome.morePointsBody": "prawym klikiem na bryle zaznacz jej środek, narożniki lub środki krawędzi punktami, które się nie drukują, a do których przyciągają się kształty. Wtedy umieścisz otwór dokładnie na środku innej części.",
  "welcome.videosTitle": "Filmy o layerling",
  "welcome.videosHint": "Zrobione przez innych, nie przez ten projekt. Linki otwierają YouTube w nowej karcie. Nic nie jest stamtąd wczytywane, dopóki nie klikniesz.",
  "welcome.help": "W edytorze grupa Pomoc zawiera krótki przewodnik i listę wszystkich skrótów klawiszowych. W stopce „Zgłoś błąd” zapisuje Twój projekt ze wszystkim, co potrzebne do zgłoszenia na forum lub na GitHubie.",
  "welcome.guideLink": "Przeczytaj pełną instrukcję z obrazkami",
