  "shell.edges.round": "Zaokrąglone",
  "shell.edges.sharp": "Ostre",
  "shell.edgesHint": "Działa tam, gdzie ścianki wewnętrzne się rozchodzą, przy stopniu lub otworze. Narożniki zwykłego prostopadłościanu zostają w środku ostre. Aby uzyskać zaokrąglone wnętrze, najpierw zaokrąglij jego zewnętrzne krawędzie.",
  "shell.apply": "Wydrąż",
  "shell.working": "Wydrążanie…",
  "shell.cancel": "Anuluj wydrążanie",
  "shell.errorTooThick": "Ścianki tej bryły nie mogą być tak grube. Wybierz cieńszą ściankę.",
  "shell.errorRoundedEdges": "Ten prostopadłościan ma zaokrąglone górne i dolne krawędzie, a ścianka musi być wyraźnie cieńsza niż to zaokrąglenie. Wybierz cieńszą ściankę albo przed wydrążeniem ustaw zaokrąglenie górnych i dolnych krawędzi na 0. Jeśli nadal się nie uda, „Zgłoś błąd” w stopce zapisze projekt do zgłoszenia.",
  "shell.errorCannotHollow": "Tej bryły nie da się wydrążyć, nawet z bardzo cienką ścianką. Jej kontur prawdopodobnie nie jest dość czysty dla jądra CAD. Może to powodować wycięcie dotykające zewnętrznej krawędzi, np. drzwi wycięte aż do dolnej krawędzi zaimportowanego kształtu.",
  "shell.errorNoFlatTop": "Ta bryła nie ma płaskiej górnej ściany, którą można zostawić otwartą. Kul i dowolnych kształtów nie da się wydrążyć w ten sposób.",
  "shell.errorNoFlatBottom": "Ta bryła nie ma płaskiej dolnej ściany, którą można zostawić otwartą.",
  "edge.errorOldRevolve": "Ta bryła obrotowa została zbudowana jako siatka przez starszą wersję layerling. Otwórz Edytuj szkic i zakończ go ponownie, aby stała się dokładną bryłą. Wtedy można ją wydrążyć, zaokrąglić i sfazować.",
  "shell.errorNoFlatSide": "Ta bryła nie ma płaskiej ściany po wybranej stronie, którą można zostawić otwartą.",
  "shell.errorProjectChanged": "Obiekt lub projekt zmienił się w trakcie wydrążania. Spróbuj ponownie.",
  "shell.errorFailed": "Nie udało się wydrążyć bryły. Wybierz inną grubość ścianki lub inne otwarcie.",
  "status.shelled": "Wydrążono ze ściankami {size} mm",
  "status.shelledClosed": "Wydrążono ze ściankami {size} mm, zamknięte ze wszystkich stron: wnęka jest w środku i widać ją tylko w widoku przekroju",
