  "offset.working": "Odsuwanie…",
  "offset.cancel": "Anuluj odsunięcie",
  "offset.errorFailed": "Nie udało się powiększyć ani zmniejszyć bryły o tę odległość. Wybierz mniejszą odległość.",
  "status.offsetGrown": "Powiększono o {size} mm",
