  "status.offsetCopy": "Dodano jako otwór bryłę odsuniętą o {size} mm",
  "status.offsetMcp": "MCP odsunęło obiekt o {size} mm",
  "edge.revertOffset": "Odsunięcie ({size} mm)",
  "historyStep.offsetOne": "Odsunięto: {name}",
  "historyStep.offsetMany": "Odsunięto obiekty: {count}",
  "guide.edges.offset": "Odsunięcie przesuwa każdą ścianę bryły o tę samą odległość, na zewnątrz lub do środka. Powiększ kopię i zachowaj ją jako otwór, a dostaniesz luz pasowania; albo zmniejsz bryłę na czop, który ma wejść w otwór. Bryły będące tylko siatką trójkątów często nie dają się odsunąć.",
  "edge.revertSurfaceTexture": "Tekstura powierzchni (głębokość {size} mm)",
  "deleteFace.title": "Usuń ścianę",
  "deleteFace.subtitle": "Sąsiednie ściany zamykają lukę",
  "deleteFace.help": "Kliknij ściany do usunięcia; kolejne kliknięcie usuwa ścianę z wyboru. Sąsiednie ściany rosną, aż luka się zamknie: zaokrąglenie, otwór albo występ znika, a bryła pozostaje dokładna.",
  "deleteFace.preparing": "Wczytywanie ścian…",
  "deleteFace.countNone": "Nie wybrano jeszcze żadnej ściany",
  "deleteFace.countOne": "Wybrano 1 ścianę",
  "deleteFace.countMany": "Wybrane ściany: {count}",
  "deleteFace.apply": "Usuń",
  "deleteFace.working": "Usuwanie ścian…",
  "deleteFace.cancel": "Anuluj usuwanie ścian",
  "deleteFace.errorUnchanged": "Tych ścian nie można usunąć: sąsiednie ściany nie zamykają luki. Wybierz wszystkie ściany tego, co ma zniknąć, na przykład wszystkie ściany zaokrąglenia albo całą ściankę otworu, i żadnej ściany samej bryły.",
  "deleteFace.errorMesh": "Ta bryła nie ma dokładnych ścian do usunięcia: layerling trzyma ją jako siatkę, tak jak zaimportowany STL, OBJ lub 3MF, podzieloną, owiniętą wokół walca lub uproszczoną bryłę albo bardzo szczegółowy kształt, na przykład długi tekst. Część zaimportowana jako STEP ma dokładne ściany.",
  "deleteFace.errorResized": "Rozmiar tej bryły zmieniono przy włączonej opcji „Zachowaj rozmiar krawędzi przy zmianie rozmiaru”, więc jej dokładne ściany nie pasują już do rozmiaru. Cofnij zmianę rozmiaru, usuń ściany, a potem znów zmień rozmiar.",
  "deleteFace.errorProjectChanged": "Obiekt lub projekt zmienił się podczas usuwania ścian; spróbuj ponownie.",
  "deleteFace.errorFailed": "Nie udało się usunąć ścian. Wybierz inne ściany.",
  "deleteFace.errorNoFaces": "Nie udało się odczytać ścian tej bryły. Zamknij narzędzie i otwórz je ponownie.",
  "deleteFace.errorTooSlow": "Usuwanie tych ścian trwało zbyt długo i zostało przerwane po 45 sekundach; nic się nie zmieniło. Jądro CAD nie radzi sobie z tymi ścianami w tej części: wybierz inne ściany lub mniej ścian.",
  "status.facesDeletedOne": "Usunięto 1 ścianę",
  "status.facesDeletedMany": "Usunięte ściany: {count}",
  "status.facesDeletedMcpOne": "MCP usunął 1 ścianę",
  "status.facesDeletedMcpMany": "MCP usunął ściany: {count}",
  "status.deleteFaceCancelled": "Anulowano usuwanie ścian",
  "status.deleteFaceCancelledChanged": "Anulowano usuwanie ścian, bo obiekt się zmienił",
  "edge.revertDeleteFaceOne": "Usunięte ściany (1 ściana)",
  "edge.revertDeleteFaceMany": "Usunięte ściany (ściany: {count})",
