  "welcome.moreLoftSketchesTitle": "Przejście między szkicami",
  "welcome.moreLoftSketchesBody": "łączy dwa szkice lub zaimportowane pliki SVG w jedną bryłę: na dole obrys dolnego, na górze obrys górnego, a między nimi proste ściany - lejek, łącznik albo z dwóch pierścieni zwężająca się rama. Edytuj grupę ponownie otwiera oba szkice.",
  "welcome.moreCookieCutterTitle": "Foremka do ciastek",
  "welcome.moreCookieCutterBody": "robi foremkę do ciastek ze szkicu, SVG albo dowolnego kształtu: cienką ściankę wokół konturu i płaski kołnierz wokół jej podstawy. Kontur jest odbity, więc tekst wychodzi z ciasta we właściwą stronę, a ścianka kończy się ostrzem. Wnętrze litery e albo a dostaje własną ściankę, trzymaną przez mostki (obniżona tylko odciska tekst w cieście), a ściankę, ostrze, wysokość i kołnierz można potem zmienić we Właściwościach.",
  "welcome.moreFlexiTitle": "Przeguby flexi",
  "welcome.moreFlexiBody": "tnie płaską bryłę (rybę, węża albo smoka, którego sam narysowałeś) na ogniwa z przegubem drukowanym na miejscu przy każdym cięciu, więc figurka po wydruku się rusza, bez podpór i bez składania.",
  "welcome.moreLidTitle": "Pokrywka",
  "welcome.moreLidBody": "robi pokrywkę do pudełka, doniczki albo tacki otwartej u góry: wciskaną w otwór, nakładaną na zewnątrz albo kładzioną płasko, z wybranym pasowaniem, gotową do druku obok.",
  "welcome.moreSlopeTitle": "Spadek i zwężenie wzdłuż",
  "welcome.moreSlopeBody": "pozwala opuścić górę prostopadłościanu, walca, klina lub okrągłego dachu ku jednemu końcowi albo zbiec jego boki ku jednemu końcowi, prosto lub łukiem: dach opadający wzdłuż, rampa, dziób łodzi.",
