  "thread.flankAngleHint": "Kąt między dwoma bokami zwoju. 60° to ostry gwint trójkątny, 30° gwint trapezowy. Przy 90° lub mniej żaden bok nie jest bardziej płaski niż 45°, więc gwint drukuje się bez podpór.",
  "prop.clearance": "Luz (XY)",
  "prop.threadChamferTop": "Fazka, górny koniec",
  "prop.threadChamferBottom": "Fazka, dolny koniec",
  "thread.axialClearanceHint": "Dodatkowy luz wzdłuż gwintu, w mm, ponad luz średnicowy: każdy zwój nakrętki staje się o tyle cieńszy, a średnica się nie zmienia. Dla gwintu, który obraca się lekko i nie grzechocze na boki: zostaw luz około 0,2 do 0,3 i ustaw tu 0,2. Przy 0 luz pochodzi tylko z luzu średnicowego, który otwiera boki zwojów mniej więcej o połowę mniej.",
  "thread.clearanceHint": "Dodatkowe miejsce na całej średnicy. Drukowany gwint potrzebuje więcej, niż się wydaje: szczelina między bokami zwojów to tylko około połowy tej wartości. Około 0,3 to ciasno, 0,4 zwykle, 0,5 luźno. Najpierw wydrukuj parę próbną.",
  "thread.boltClearanceHint": "Pocienia śrubę o tyle, dla metalowej nakrętki, która nie ma własnego luzu (0,3 do 0,4, tyle co miałaby drukowana nakrętka). Z drukowaną nakrętką zostaw 0 i daj luz nakrętce.",
