  "prop.hingeScrewAcrossHint": "Od otworu w jednym skrzydełku do otworu w drugim, od środka do środka. 0 stawia każdy otwór na środku jego skrzydełka.",
  "prop.gridfinityType": "Rodzaj",
  "gridfinity.bin": "Pojemnik",
  "gridfinity.baseplate": "Podstawka",
  "gridfinity.binHint": "Pojemnik na siatce Gridfinity 42 mm: stoi w podstawce i daje się ustawiać na innych pojemnikach, także z innych generatorów Gridfinity.",
  "gridfinity.baseplateHint": "Podstawka, w której stoją pojemniki Gridfinity, wysoka na 5 mm: jedno gniazdo na każdą jednostkę siatki 42 mm.",
  "gridfinity.tray": "Tacka",
  "gridfinity.trayHint": "Tacka dowolnego rozmiaru w mm z płaskim dnem, na wkładki do gier planszowych i drobne części: bez stopek i bez kołnierza piętrowania, więc nie stoi w podstawce i nie da się jej piętrować. Przegrody i półki na etykietę sięgają do góry.",
  "prop.gridfinityUnitsX": "Jednostki wszerz",
  "prop.gridfinityUnitsZ": "Jednostki w głąb",
  "prop.gridfinityUnitsY": "Jednostki wysokości",
  "prop.gridfinityLip": "Kołnierz piętrowania",
  "prop.gridfinityLipChamfer": "Fazka kołnierza",
  "gridfinity.lipChamferHint": "Fazuje górną krawędź kołnierza piętrowania; przy 0 pozostaje ostra, tak jak rysuje ją specyfikacja Gridfinity.",
  "prop.gridfinityMagnets": "Otwory na magnesy",
  "prop.gridfinityHalfGrid": "Siatka połówkowa (21 mm)",
  "gridfinity.halfGridHint": "Jednostki wszerz i w głąb liczą komórki po 21 mm, każdą z własną stopką; cztery stoją w jednym gnieździe podstawki.",
  "prop.gridfinityFloorHeight": "Wysokość dna",
  "gridfinity.floorHeightHint": "Do tej wysokości, mierząc od spodu, pojemnik jest pełny: półfabrykat, w którym wytniesz kształty.",
  "prop.gridfinityWallThickness": "Grubość ścianki",
  "gridfinity.wallThicknessHint": "Ścianka jest mierzona od strony zewnętrznej, która się nie zmienia. Z kołnierzem piętrowania ścianka grubsza niż 1,75 mm kończy się występem 0,85 mm poniżej 7 mm na jednostkę wysokości, nie dotykając stopek pojemnika postawionego na górze.",
  "prop.gridfinityOpenBack": "Otwarty z tyłu",
  "prop.gridfinityOpenFront": "Otwarty z przodu",
