  "export.3mf.description": "Projekt slicera z kolorami",
  "export.3mf.note": "Dla PrusaSlicer, Bambu Studio, OrcaSlicer i Cura. Każda bryła zostaje osobną częścią ze swoją nazwą i kolorem.",
  "export.obj.description": "Uniwersalna siatka 3D",
  "export.obj.note": "Szeroko obsługiwany format siatki do modelowania, renderowania i wymiany. Kolory są zapisywane w wierzchołkach, co odczytują Bambu Studio i OrcaSlicer.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "Zachowuje prostopadłościany, walce, kule i stożki jako dokładną geometrię CAD, razem ze wszystkim, czego krawędzie zaokrąglono lub sfazowano, oraz bryłami zaimportowanymi jako STEP. Gwinty, sprężyny i koła zębate też trafiają jako dokładne bryły, podobnie kształty zwężone, pochylone i skręcone. Na przykład zaimportowane siatki wykraczają poza STEP, te trafiają jako STL.",
  "export.svg.description": "Wektor z widoku z góry",
  "export.svg.note": "Eksportuje czystą sylwetkę z widoku z góry w milimetrach, z otworami i zakrzywionymi konturami.",
  "export.svg.noteFootprint": "Eksportuje tylko obrysy, którymi obiekty stoją na płaszczyźnie roboczej, jako linie w milimetrach, do cięcia laserem i szablonów.",
  "export.svg.noteEdges": "Eksportuje krawędzie widoczne z góry jako linie w milimetrach, każdą bryłę w jej kolorze: kontury, otwory, kieszenie i grawerunki, każdy obszar zamknięty, do grawerowania laserem i dla plotterów.",
  "export.svg.view": "Widok",
