  "export.bridges": "Mostki dla części, które by wypadły",
  "export.bridgesHint": "Część wewnątrz wycięcia (środek litery „o”, brzuszek litery „b”) wypada po wycięciu dookoła. Małe mostki trzymają ją na miejscu, jak w szablonie.",
