  "export.svg.viewEdges": "Widoczne krawędzie z góry",
  "export.dxf.description": "Obrys do cięcia laserem",
  "export.dxf.note": "Eksportuje obrys z góry dla firm tnących laserem: linie, prawdziwe łuki i okręgi na warstwie 0 w kolorze białym, w milimetrach. Stykające się bryły tworzą jeden obrys.",
  "export.dxf.noteFootprint": "Eksportuje tylko obrysy, którymi obiekty stoją na płaszczyźnie roboczej, dla firm tnących laserem: linie, prawdziwe łuki i okręgi na warstwie 0 w kolorze białym, w milimetrach.",
  "export.lyl.description": "Własny format projektu layerling",
  "export.lyl.note": "Zachowuje edytowalny projekt, historię cofania i ponawiania, szkice, grupy, dane CAD i zaimportowane źródła. Starsze pliki .skf też się otwierają i są zapisywane jako .lyl. W Chrome i Edge sam wybierasz folder i nazwę, a Ctrl+S zapisuje potem znów do tego pliku. Projekt otwarty z pliku zapisuje się z powrotem do niego.",
